async function mountCharts(rawData) {
  clearCharts();
  let Apex;
  try {
    Apex = await loadApex();
  } catch (e) {
    console.error('[Stocks] Failed to load chart library:', e);
    // Show fallback message in all chart containers
    rootEl.querySelectorAll('.stocks-page__chart').forEach(c => {
      c.innerHTML = `<div style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--c-text-3);font-size:var(--text-sm);">
        <span style="margin-right:var(--s-2);">${icons['alert-circle']}</span> Gagal memuat chart library
      </div>`;
    });
    return;
  }

  const containers = rootEl.querySelectorAll('.stocks-page__chart');
  if (!containers.length) {
    console.warn('[Stocks] No chart containers found');
    return;
  }

  // Normalize dates once
  const normData = rawData.map(d => ({...d, date: normalizeDate(d.date)}));

  containers.forEach((container, idx) => {
    const type = container.dataset.chartType;
    let chart = null;
    try {
      if (type === 'Pergerakan Harga' || type === 'Perbandingan Harga (Normalisasi)') {
        chart = state.compareMode && state.compareTickers.length
          ? buildCompareChart(container, normData, state.compareData, state.compareTickers, Apex)
          : buildPriceChart(container, normData, Apex);
      } else if (type === 'Total Nilai Transaksi') {
        chart = buildBarChart(container, normData.map(d => ({ date: d.date, value: d.value })), '#F6903D', Apex);
      } else if (type === 'Volume Perdagangan') {
        chart = buildBarChart(container, normData.map(d => ({ date: d.date, value: d.volume })), '#6DC8EC', Apex);
      } else if (type === 'Arus Dana Asing') {
        chart = buildForeignChart(container, normData, Apex);
      } else if (type === 'BII Score (Buying Intensity Index)') {
        chart = buildLineChart(container, normData.map(d => ({ date: d.date, close: d.biiScore })), '#7B61FF', Apex);
      } else if (type === 'ATV (Avg Transaction Value)') {
        chart = buildBarChart(container, normData.map(d => ({ date: d.date, value: d.atv })), '#9270CA', Apex);
      } else if (type === 'Nilai Nego (Non-Regular)') {
        chart = buildBarChart(container, normData.map(d => ({ date: d.date, value: d.nonRegValue })), '#F6C022', Apex);
      } else if (type === 'Frekuensi Nego') {
        chart = buildBarChart(container, normData.map(d => ({ date: d.date, value: d.nonRegFreq })), '#90A4AE', Apex);
      }
      if (chart) {
        state.charts.push(chart);
        console.log(`[Stocks] Chart "${type}" mounted successfully`);
      }
    } catch (e) {
      console.error(`[Stocks] Chart "${type}" failed:`, e);
      container.innerHTML = `<div style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--c-text-3);font-size:var(--text-sm);">
        <span style="margin-right:var(--s-2);">${icons['alert-circle']}</span> Chart error
      </div>`;
    }
  });
}

/* ─── ApexCharts lazy loader ─── */
let apexPromise = null;
async function loadApex() {
  if (apexPromise) return apexPromise;
  apexPromise = (async () => {
    // Try esm.sh first
    try {
      const mod = await import('https://esm.sh/apexcharts@4.7.0');
      const Apex = mod.default || mod;
      if (typeof Apex === 'function') {
        console.log('[Stocks] ApexCharts loaded via esm.sh');
        return Apex;
      }
    } catch (e) {
      console.warn('[Stocks] esm.sh ApexCharts failed:', e.message);
    }
    // Fallback: script tag from jsDelivr
    try {
      await new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/npm/apexcharts@4.7.0/dist/apexcharts.min.js';
        script.onload = () => resolve();
        script.onerror = () => reject(new Error('jsDelivr ApexCharts failed'));
        document.head.appendChild(script);
      });
      if (window.ApexCharts) {
        console.log('[Stocks] ApexCharts loaded via jsDelivr');
        return window.ApexCharts;
      }
      throw new Error('window.ApexCharts not available after script load');
    } catch (e) {
      console.error('[Stocks] All ApexCharts loaders failed:', e.message);
      throw e;
    }
  })();
  return apexPromise;
}

function getApexTheme() {
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
  return {
    mode: isDark ? 'dark' : 'light',
    text: isDark ? '#a3a3a3' : '#616161',
    grid: isDark ? '#2a2a2a' : '#e0e0e0',
  };
}

function makeApexOptions(container, height, type) {
  const t = getApexTheme();
  return {
    chart: {
      type,
      width: '100%',
      height: container.clientHeight || height,
      background: 'transparent',
      foreColor: t.text,
      fontFamily: "'Roboto', system-ui, -apple-system, sans-serif",
      toolbar: { show: false },
      zoom: { enabled: false },
      animations: { enabled: false },
      redrawOnParentResize: true,
    },
    grid: {
      borderColor: t.grid,
      xaxis: { lines: { show: false } },
      yaxis: { lines: { show: true } },
      padding: { top: 0, right: 4, bottom: 0, left: 4 },
    },
    xaxis: {
      categories: [],
      axisBorder: { show: false },
      axisTicks: { show: false },
      tickAmount: 6,
      labels: {
        hideOverlappingLabels: true,
        trim: true,
        rotate: 0,
        maxHeight: 30,
        formatter: (val) => dateLabel(val),
      },
    },
    yaxis: {
      labels: { formatter: (val) => compact(val) },
    },
    dataLabels: { enabled: false },
    legend: { show: false },
    tooltip: { theme: t.mode, x: { show: true } },
    stroke: { width: 2.5, curve: 'straight' },
  };
}

function renderApex(container, options, Apex) {
  container.innerHTML = '';
  const chart = new Apex(container, options);
  chart.render();
  return chart;
}

function buildPriceChart(container, data, Apex) {
  const rows = data.filter(d => d.date && d.close != null);
  const options = makeApexOptions(container, 270, 'line');
  options.series = [{ name: 'Harga', data: rows.map(d => d.close) }];
  options.xaxis.categories = rows.map(d => d.date);
  options.colors = ['#00A86B'];
  options.tooltip.y = { formatter: (v) => fmtPrice(v) };
  return renderApex(container, options, Apex);
}

function buildBarChart(container, data, color, Apex) {
  const rows = data.filter(d => d.date && d.value != null);
  const options = makeApexOptions(container, 200, 'bar');
  options.series = [{ name: 'Nilai', data: rows.map(d => d.value) }];
  options.xaxis.categories = rows.map(d => d.date);
  options.colors = [color];
  options.plotOptions = { bar: { columnWidth: '80%', borderRadius: 1 } };
  options.tooltip.y = { formatter: (v) => compact(v) };
  return renderApex(container, options, Apex);
}

function buildForeignChart(container, data, Apex) {
  const rows = data.filter(d => d.date && d.netForeign != null);
  const options = makeApexOptions(container, 210, 'bar');
  options.series = [{ name: 'Net Foreign', data: rows.map(d => d.netForeign) }];
  options.xaxis.categories = rows.map(d => d.date);
  options.plotOptions = {
    bar: {
      columnWidth: '80%',
      borderRadius: 1,
      colors: {
        ranges: [
          { from: -1000000000000000, to: -0.001, color: '#D94B4B' },
          { from: -0.001, to: 1000000000000000, color: '#00A86B' },
        ],
      },
    },
  };
  options.tooltip.y = { formatter: (v) => compact(v) };
  return renderApex(container, options, Apex);
}

function buildLineChart(container, data, color, Apex) {
  const rows = data.filter(d => d.date && d.close != null);
  const options = makeApexOptions(container, 210, 'line');
  options.series = [{ name: 'Nilai', data: rows.map(d => d.close) }];
  options.xaxis.categories = rows.map(d => d.date);
  options.colors = [color];
  return renderApex(container, options, Apex);
}

function buildCompareChart(container, primaryData, compareData, compareTickers, Apex) {
  const validPrimary = primaryData.filter(d => d.date && d.close != null);
  const base1 = validPrimary[0]?.close || 1;
  const cats = validPrimary.map(d => d.date);
  const series = [{
    name: state.analysis?.ticker || 'Saham',
    data: validPrimary.map(d => ((d.close - base1) / base1) * 100),
  }];
  compareTickers.forEach(t => {
    const cd = compareData[t];
    if (!cd || !cd.length) return;
    const valid = cd.filter(d => d.date && d.close != null);
    if (!valid.length) return;
    const base = valid[0].close || 1;
    const byDate = {};
    valid.forEach(d => { byDate[normalizeDate(d.date)] = ((d.close - base) / base) * 100; });
    series.push({ name: t, data: cats.map(c => (c in byDate ? byDate[c] : null)) });
  });
  const options = makeApexOptions(container, 300, 'line');
  options.series = series;
  options.xaxis.categories = cats;
  options.colors = COMPARE_COLORS.slice(0, series.length);
  options.stroke = { width: series.map((_, i) => (i === 0 ? 2.5 : 2)), curve: 'straight' };
  options.tooltip.shared = true;
  options.tooltip.y = { formatter: (v) => (v == null ? '-' : v.toFixed(2) + '%') };
  return renderApex(container, options, Apex);
}

async function mountMarketCharts(ewi, mci, marketData) {
  clearCharts();
  if (!marketData.length) return;
  let Apex;
  try {
    Apex = await loadApex();
  } catch (e) {
    console.error('[Market] Failed to load chart library:', e);
    rootEl.querySelectorAll('.market-page__chart').forEach(c => {
      c.innerHTML = `<div style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--c-text-3);font-size:var(--text-sm);">
        <span style="margin-right:var(--s-2);">${icons['alert-circle']}</span> Gagal memuat chart library
      </div>`;
    });
    return;
  }
  const containers = rootEl.querySelectorAll('.market-page__chart');
  containers.forEach(container => {
    const type = container.dataset.chartType;
    let chart;
    try {
      if (type === 'EWI vs MCI') chart = buildEwiMciChart(container, ewi, mci, Apex);
      else if (type === 'Total Nilai Transaksi Pasar') chart = buildBarChart(container, marketData.map(d => ({ date: d.date, value: d.value })), '#F6903D', Apex);
      else if (type === 'Frekuensi Transaksi Pasar') chart = buildBarChart(container, marketData.map(d => ({ date: d.date, value: d.frequency })), '#5B8FF9', Apex);
      else if (type === 'ATV Pasar') chart = buildBarChart(container, marketData.map(d => ({ date: d.date, value: d.atv })), '#9270CA', Apex);
      else if (type === 'Arus Dana Asing Pasar') chart = buildForeignMarketChart(container, marketData, Apex);
      else if (type === 'BII Score Pasar') chart = buildLineChart(container, marketData.map(d => ({ date: d.date, close: d.bii_score })), '#7B61FF', Apex);
      else if (type === 'Nilai Nego Pasar') chart = buildBarChart(container, marketData.map(d => ({ date: d.date, value: d.non_reg_value })), '#F6C022', Apex);
      else if (type === 'Frekuensi Nego Pasar') chart = buildBarChart(container, marketData.map(d => ({ date: d.date, value: d.non_reg_freq })), '#90A4AE', Apex);
      if (chart) state.charts.push(chart);
    } catch (e) {
      console.error(`[Market] Chart "${type}" failed:`, e);
      container.innerHTML = `<div style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--c-text-3);font-size:var(--text-sm);">
        <span style="margin-right:var(--s-2);">${icons['alert-circle']}</span> Chart error
      </div>`;
    }
  });
}

